import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Stack Tecnológica Oficial do SoftForge","description":"","frontmatter":{},"headers":[],"relativePath":"pt-br/06-stack-tecnologica.md","filePath":"pt-br/06-stack-tecnologica.md"}'),n={name:"pt-br/06-stack-tecnologica.md"};function l(d,t,i,r,c,p){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="stack-tecnologica-oficial-do-softforge" tabindex="-1">Stack Tecnológica Oficial do SoftForge <a class="header-anchor" href="#stack-tecnologica-oficial-do-softforge" aria-label="Permalink to &quot;Stack Tecnológica Oficial do SoftForge&quot;">​</a></h1><blockquote><p><strong>A fundação tecnológica moderna, orientada a contratos e otimizada para operação por Agentes de IA.</strong></p></blockquote><hr><h2 id="_1-visao-geral-da-stack" tabindex="-1">1. Visão Geral da Stack <a class="header-anchor" href="#_1-visao-geral-da-stack" aria-label="Permalink to &quot;1. Visão Geral da Stack&quot;">​</a></h2><p>O SoftForge foi desenhado com base em um critério rigoroso: <strong>cada tecnologia da stack deve ser determinística, fortemente tipada e com superfície de contexto ideal para Agentes de IA (LLMs) e desenvolvedores humanos.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        FRONTEND (apps/web)                             │</span></span>
<span class="line"><span>│      React + TypeScript + Vite + Tailwind CSS + shadcn/ui             │</span></span>
<span class="line"><span>│      TanStack Query (React Query v5) + Lucide Icons                    │</span></span>
<span class="line"><span>└───────────────────────────────────▲────────────────────────────────────┘</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                       Contrato OpenAPI 3.1 &amp; DTOs</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>┌───────────────────────────────────▼────────────────────────────────────┐</span></span>
<span class="line"><span>│                         BACKEND (apps/api)                             │</span></span>
<span class="line"><span>│     Python 3.12+ + FastAPI + Pydantic v2 + SQLAlchemy 2.0 Async        │</span></span>
<span class="line"><span>│     Loguru (Logs Estruturados) + JWT/HttpOnly Cookies + Ruff Linter    │</span></span>
<span class="line"><span>└───────────────────▲────────────────────────────────▲───────────────────┘</span></span>
<span class="line"><span>                    │                                │</span></span>
<span class="line"><span>    (Ambiente de Testes / CI)             (Produção / Local Docker)</span></span>
<span class="line"><span>                    │                                │</span></span>
<span class="line"><span>┌───────────────────▼──────────────┐ ┌───────────────▼───────────────────┐</span></span>
<span class="line"><span>│     SQLite In-Memory             │ │      PostgreSQL 16+               │</span></span>
<span class="line"><span>│     (Execução em ~2 segundos)    │ │      (Persistência e Concorrência)│</span></span>
<span class="line"><span>└──────────────────────────────────┘ └───────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-backend-core-apps-api" tabindex="-1">2. Backend Core (<code>apps/api</code>) <a class="header-anchor" href="#_2-backend-core-apps-api" aria-label="Permalink to &quot;2. Backend Core (\`apps/api\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tecnologia</th><th style="text-align:left;">Versão</th><th style="text-align:left;">Papel no SoftForge</th><th style="text-align:left;">Por que foi escolhida?</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Python</strong></td><td style="text-align:left;"><code>3.12+</code></td><td style="text-align:left;">Linguagem base da API</td><td style="text-align:left;">Suporte a generics modernos de tipo (<code>type</code>, <code>TypeVar</code>), alta legibilidade para modelos de IA e ecossistema robusto.</td></tr><tr><td style="text-align:left;"><strong>FastAPI</strong></td><td style="text-align:left;"><code>0.115+</code></td><td style="text-align:left;">Framework HTTP &amp; Roteamento</td><td style="text-align:left;">Geração automática de OpenAPI 3.1, injeção de dependências nativa e alta performance assíncrona com <code>asyncio</code>.</td></tr><tr><td style="text-align:left;"><strong>Pydantic</strong></td><td style="text-align:left;"><code>v2.10+</code></td><td style="text-align:left;">Validação de Dados &amp; DTOs</td><td style="text-align:left;">Núcleo escrito em Rust (ultra-rápido), validação rigorosa de esquemas e conversão bidirecional com tipagem estrita.</td></tr><tr><td style="text-align:left;"><strong>SQLAlchemy</strong></td><td style="text-align:left;"><code>2.0+ (Async)</code></td><td style="text-align:left;">ORM &amp; Query Builder</td><td style="text-align:left;">Padrão da indústria para Python; sintaxe tipada com <code>Mapped[...]</code>, suporte assíncrono nativo com <code>AsyncSession</code>.</td></tr><tr><td style="text-align:left;"><strong>Loguru</strong></td><td style="text-align:left;"><code>0.7+</code></td><td style="text-align:left;">Observabilidade &amp; Logs</td><td style="text-align:left;">Logs estruturados em JSON ou coloridos no terminal, com injeção automática de <code>X-Request-ID</code> para rastreabilidade.</td></tr><tr><td style="text-align:left;"><strong>PyJWT &amp; Passlib</strong></td><td style="text-align:left;">Recente</td><td style="text-align:left;">Segurança &amp; Autenticação</td><td style="text-align:left;">Hashing seguro de senhas (Argon2 / bcrypt) e emissão de tokens JWT com dupla camada (HttpOnly cookie + Bearer header).</td></tr><tr><td style="text-align:left;"><strong>Ruff</strong></td><td style="text-align:left;"><code>0.9+</code></td><td style="text-align:left;">Linter e Formatador</td><td style="text-align:left;">Escrito em Rust; substitui Flake8, Black e isort com velocidade instantânea (&lt;100ms), mantendo o código impecável.</td></tr><tr><td style="text-align:left;"><strong>Pytest &amp; pytest-asyncio</strong></td><td style="text-align:left;"><code>8.0+</code></td><td style="text-align:left;">Suíte de Testes</td><td style="text-align:left;">Execução assíncrona isolada com fixtures para sessões de banco e cliente HTTP de teste (<code>httpx</code>).</td></tr></tbody></table><hr><h2 id="_3-frontend-core-apps-web" tabindex="-1">3. Frontend Core (<code>apps/web</code>) <a class="header-anchor" href="#_3-frontend-core-apps-web" aria-label="Permalink to &quot;3. Frontend Core (\`apps/web\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tecnologia</th><th style="text-align:left;">Versão</th><th style="text-align:left;">Papel no SoftForge</th><th style="text-align:left;">Por que foi escolhida?</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>React</strong></td><td style="text-align:left;"><code>18+ / 19</code></td><td style="text-align:left;">Biblioteca de UI</td><td style="text-align:left;">Padrão universal para SPAs; ampla compatibilidade e facilidade de manipulação por agentes de código.</td></tr><tr><td style="text-align:left;"><strong>TypeScript</strong></td><td style="text-align:left;"><code>5.0+</code></td><td style="text-align:left;">Superset tipado</td><td style="text-align:left;">Garante que os modelos e DTOs gerados a partir do OpenAPI 3.1 sejam respeitados em tempo de compilação.</td></tr><tr><td style="text-align:left;"><strong>Vite</strong></td><td style="text-align:left;"><code>6.0+</code></td><td style="text-align:left;">Build Tool &amp; Bundler</td><td style="text-align:left;">HMR (Hot Module Replacement) instantâneo, compilação via esbuild/Rollup e inicialização ultrarrápida.</td></tr><tr><td style="text-align:left;"><strong>Tailwind CSS</strong></td><td style="text-align:left;"><code>3.4+</code></td><td style="text-align:left;">Estilização Utilitária</td><td style="text-align:left;">Design system consistente, zero overhead de arquivos CSS separados e sem colisões de classes globais.</td></tr><tr><td style="text-align:left;"><strong>shadcn/ui &amp; Radix</strong></td><td style="text-align:left;">Padrão</td><td style="text-align:left;">Biblioteca de Componentes</td><td style="text-align:left;">Acessibilidade (WAI-ARIA) por padrão, componentes não-opacados (código vive no repo) e customização total.</td></tr><tr><td style="text-align:left;"><strong>TanStack Query</strong></td><td style="text-align:left;"><code>v5</code></td><td style="text-align:left;">Gerenciamento de Estado Server</td><td style="text-align:left;">Cache inteligente, revalidação em segundo plano, mutações assíncronas e controle de loading/error sem boilerplate.</td></tr><tr><td style="text-align:left;"><strong>Lucide Icons</strong></td><td style="text-align:left;">Recente</td><td style="text-align:left;">Conjunto de Ícones</td><td style="text-align:left;">Ícones vetoriais leves, consistentes e fáceis de importar dinamicamente.</td></tr></tbody></table><hr><h2 id="_4-persistencia-de-dados-ambientes" tabindex="-1">4. Persistência de Dados &amp; Ambientes <a class="header-anchor" href="#_4-persistencia-de-dados-ambientes" aria-label="Permalink to &quot;4. Persistência de Dados &amp; Ambientes&quot;">​</a></h2><p>O SoftForge adota uma estratégia <strong>híbrida e inteligente</strong> de banco de dados:</p><ol><li><strong>Testes &amp; Protótipos Locais (SQLite In-Memory):</strong><ul><li>Os testes de integração em <code>apps/api/src/slices/*/tests/</code> usam <code>sqlite+aiosqlite:///:memory:</code>.</li><li><strong>Vantagem:</strong> Toda a suíte de testes do monorepo roda em <strong>menos de 3 segundos</strong> sem necessitar de containers Docker ligados ou portas de rede abertas.</li></ul></li><li><strong>Produção e Staging (PostgreSQL 16+):</strong><ul><li>Utilizado em ambientes de produção e via <code>docker compose up</code> local.</li><li>Suporte nativo a tipos UUID, índices concorrentes e isolamento transacional ACID.</li></ul></li></ol><hr><h2 id="_5-ferramental-de-agentes-de-ia-tools-scripts" tabindex="-1">5. Ferramental de Agentes de IA (<code>tools/scripts/</code>) <a class="header-anchor" href="#_5-ferramental-de-agentes-de-ia-tools-scripts" aria-label="Permalink to &quot;5. Ferramental de Agentes de IA (\`tools/scripts/\`)&quot;">​</a></h2><p>Ferramentas nativas do repositório para garantir que qualquer IA (Cursor, Antigravity, Claude Code, Copilot) opere sem degradar a base:</p><ol><li><strong><code>tools/scripts/slice_scaffold.py</code>:</strong><ul><li>Cria o esqueleto completo de uma nova fatia vertical (<code>schemas.py</code>, <code>models.py</code>, <code>service.py</code>, <code>router.py</code>, <code>tests/</code>) já com tipagem estrita e convenções prontas.</li></ul></li><li><strong><code>tools/scripts/export_openapi.py</code>:</strong><ul><li>Extrai a especificação OpenAPI 3.1 oficial para <code>docs/openapi.json</code> e <code>contracts/openapi.json</code>.</li></ul></li><li><strong><code>tools/scripts/verify.py</code>:</strong><ul><li>Gatekeeper de qualidade: roda o Ruff linter, verifica sintaxe e executa 100% dos testes Pytest antes de qualquer commit ou aprovação de tarefa.</li></ul></li></ol><hr><h2 id="_6-documentacao-visualizacao-offline" tabindex="-1">6. Documentação &amp; Visualização Offline <a class="header-anchor" href="#_6-documentacao-visualizacao-offline" aria-label="Permalink to &quot;6. Documentação &amp; Visualização Offline&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Ferramenta</th><th style="text-align:left;">Localização</th><th style="text-align:left;">Função</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>VitePress</strong></td><td style="text-align:left;"><code>docs/</code></td><td style="text-align:left;">Gerador de documentação estática bilíngue com suporte a tema escuro/claro e motor de busca local (<em>minisearch</em>).</td></tr><tr><td style="text-align:left;"><strong><code>docs.bat</code> / <code>docs.ps1</code></strong></td><td style="text-align:left;">Raiz (<code>/</code>)</td><td style="text-align:left;">Scripts de inicialização rápida que servem os arquivos estáticos pré-compilados em <code>http://localhost:5174</code>.</td></tr><tr><td style="text-align:left;"><strong><code>manual-offline.html</code></strong></td><td style="text-align:left;"><code>docs/</code></td><td style="text-align:left;">Manual zero-dependências com CSS 100% inlined. Funciona diretamente com duplo clique via <code>file:///</code>.</td></tr></tbody></table>`,23)])])}const f=e(n,[["render",l]]);export{m as __pageData,f as default};
